SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS pct_public_dc
FROM gishub.fleet.charging_sessions;

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / NULLIF(SUM(energy_kwh), 0) AS pct_public_dc
FROM gishub.fleet.charging_sessions;

SELECT COUNT(DISTINCT fe.event_id) AS total_fault_events, COUNT(DISTINCT wc.event_id) AS fault_events_with_claims
FROM gishub.fleet.fault_events fe
LEFT JOIN gishub.fleet.warranty_claims wc ON fe.event_id = wc.event_id;

SELECT SUM(cost_eur) AS total_warranty_cost_2027
FROM gishub.fleet.warranty_claims
WHERE YEAR(opened_at) = 2027;

SELECT SUM(cost_eur) AS total_warranty_cost_2027
FROM gishub.fleet.warranty_claims
WHERE CAST(EXTRACT(year FROM opened_at) AS INT) = 2027;
